import type { GuideBlock, TLang } from '../../src/data/types';
export const GUIDE_TEXT: Record<string, Record<TLang, { title: string; blocks: GuideBlock[] }>> = {"t00":{"en":{"title":"Driving licence and its categories","blocks":[{"text":"Private: age 18 or over (a temporary permit for a maximum of one year from age 17), completing training at a driving school, passing the theory and practical tests, paying the fees, and settling any previous violations."},{"text":"The private licence is valid for up to 10 years and allows carrying a maximum of 9 people including the driver, and driving small vehicles weighing no more than 3500 kg."},{"text":"Public: age 20 or over, valid for 5 years. Category 1: taxi (up to 8 passengers); Category 2: light transport (up to 3500 kg) or heavy transport (more than that); Category 3: buses (small: 15 passengers or fewer; large: more)."},{"text":"Public works vehicles: age 20, valid for 5 years. Motorcycle: age 18, valid for 10 years."},{"text":"Non-Saudis must have legal residency, be free of diseases and disabilities that prevent driving, and have no court ruling for certain crimes (assault or drugs) unless their record has been officially cleared."},{"text":"The licence contains: name, ID number, date of birth, restrictions, sex, blood group, issue and expiry dates, and nationality."}]},"ur":{"title":"ڈرائیونگ لائسنس اور اس کی اقسام","blocks":[{"text":"پرائیویٹ: عمر 18 سال یا اس سے زیادہ (17 سال کی عمر سے زیادہ سے زیادہ ایک سال کے لیے عارضی اجازت نامہ)، ڈرائیونگ اسکول میں تربیت مکمل کرنا، نظری اور عملی ٹیسٹ پاس کرنا، فیس ادا کرنا، اور پچھلی خلاف ورزیوں کے جرمانے ادا کرنا۔"},{"text":"پرائیویٹ لائسنس 10 سال تک کارآمد ہوتا ہے، اس سے ڈرائیور سمیت زیادہ سے زیادہ 9 افراد کو لے جانے اور 3500 کلوگرام سے زیادہ وزن نہ رکھنے والی چھوٹی گاڑیاں چلانے کی اجازت ملتی ہے۔"},{"text":"پبلک: عمر 20 سال یا اس سے زیادہ اور 5 سال کی مدت۔ کیٹیگری 1 ٹیکسی (8 مسافروں تک)، کیٹیگری 2 ہلکی ٹرانسپورٹ (3500 کلوگرام تک) یا بھاری ٹرانسپورٹ (اس سے زیادہ)، کیٹیگری 3 بسیں (چھوٹی 15 یا کم مسافر، بڑی اس سے زیادہ)۔"},{"text":"پبلک ورکس کی گاڑیاں: 20 سال عمر اور 5 سال مدت۔ موٹر سائیکل: 18 سال عمر اور 10 سال مدت۔"},{"text":"غیر سعودیوں کے لیے قانونی اقامہ، ڈرائیونگ میں رکاوٹ بننے والی بیماریوں اور معذوریوں سے پاک ہونا، اور بعض جرائم (حملہ یا منشیات) میں عدالتی فیصلہ نہ ہونا شرط ہے، الا یہ کہ ان کا ریکارڈ باضابطہ طور پر صاف ہو چکا ہو۔"},{"text":"لائسنس میں یہ معلومات ہوتی ہیں: نام، شناختی نمبر، تاریخ پیدائش، پابندیاں، قسم، بلڈ گروپ، اجرا اور اختتام کی تاریخ، اور قومیت۔"}]},"hi":{"title":"ड्राइविंग लाइसेंस और उसकी श्रेणियाँ","blocks":[{"text":"प्राइवेट: उम्र 18 साल या उससे ज़्यादा (17 साल की उम्र से अस्थायी परमिट, ज़्यादा से ज़्यादा एक साल के लिए), ड्राइविंग स्कूल में ट्रेनिंग पूरी करना, थ्योरी और प्रैक्टिकल टेस्ट पास करना, फीस भरना, और पिछले उल्लंघनों का जुर्माना चुकाना।"},{"text":"प्राइवेट लाइसेंस 10 साल तक वैध रहता है। इससे ड्राइवर सहित ज़्यादा से ज़्यादा 9 लोगों को ले जा सकते हैं, और 3500 किग्रा से ज़्यादा वज़न न रखने वाले छोटे वाहन चला सकते हैं।"},{"text":"पब्लिक: उम्र 20 साल या उससे ज़्यादा, 5 साल के लिए वैध। श्रेणी 1: टैक्सी (8 यात्रियों तक); श्रेणी 2: हल्का परिवहन (3500 किग्रा तक) या भारी परिवहन (उससे ज़्यादा); श्रेणी 3: बसें (छोटी: 15 या उससे कम यात्री; बड़ी: उससे ज़्यादा)।"},{"text":"सार्वजनिक निर्माण कार्य (पब्लिक वर्क्स) के वाहन: उम्र 20 साल, 5 साल के लिए वैध। मोटरसाइकिल: उम्र 18 साल, 10 साल के लिए वैध।"},{"text":"गैर-सऊदी लोगों के लिए ज़रूरी है: वैध इक़ामा (कानूनी निवास), ड्राइविंग में रुकावट डालने वाली बीमारियों और विकलांगताओं से मुक्त होना, और कुछ अपराधों (मारपीट या नशीले पदार्थ) में कोई अदालती फैसला न होना, जब तक कि उनका रिकॉर्ड आधिकारिक रूप से साफ़ न हो गया हो।"},{"text":"लाइसेंस में होता है: नाम, आईडी नंबर, जन्म तिथि, प्रतिबंध, प्रकार, ब्लड ग्रुप, जारी होने और समाप्त होने की तारीख, और राष्ट्रीयता।"}]},"bn":{"title":"ড্রাইভিং লাইসেন্স ও এর শ্রেণি","blocks":[{"text":"প্রাইভেট: বয়স 18 বছর বা তার বেশি (17 বছর বয়স থেকে সর্বোচ্চ এক বছরের জন্য অস্থায়ী অনুমতিপত্র), ড্রাইভিং স্কুলে প্রশিক্ষণ শেষ করা, তত্ত্বীয় ও ব্যবহারিক পরীক্ষায় পাস করা, ফি দেওয়া, এবং আগের লঙ্ঘনের জরিমানা পরিশোধ করা।"},{"text":"প্রাইভেট লাইসেন্স সর্বোচ্চ 10 বছর পর্যন্ত বৈধ থাকে। এটি দিয়ে চালকসহ সর্বোচ্চ 9 জন বহন করা যায় এবং 3500 কেজির বেশি ওজন নয় এমন ছোট গাড়ি চালানো যায়।"},{"text":"পাবলিক: বয়স 20 বছর বা তার বেশি, মেয়াদ 5 বছর। শ্রেণি 1: ট্যাক্সি (8 জন যাত্রী পর্যন্ত); শ্রেণি 2: হালকা পরিবহন (3500 কেজি পর্যন্ত) বা ভারী পরিবহন (এর বেশি); শ্রেণি 3: বাস (ছোট: 15 জন বা তার কম যাত্রী; বড়: এর বেশি)।"},{"text":"নির্মাণকাজের (ভারী যন্ত্রপাতির) যানবাহন: বয়স 20 বছর, মেয়াদ 5 বছর। মোটরসাইকেল: বয়স 18 বছর, মেয়াদ 10 বছর।"},{"text":"অ-সৌদিদের জন্য শর্ত: বৈধ ইকামা (আইনসম্মত বসবাসের অনুমতি) থাকা, গাড়ি চালাতে বাধা দেয় এমন রোগ ও অক্ষমতা থেকে মুক্ত থাকা, এবং নির্দিষ্ট কিছু অপরাধে (হামলা বা মাদক) কোনো আদালতের রায় না থাকা, যদি না তাদের রেকর্ড আনুষ্ঠানিকভাবে পরিষ্কার করা হয়ে থাকে।"},{"text":"লাইসেন্সে থাকে: নাম, আইডি নম্বর, জন্ম তারিখ, বিধিনিষেধ, ধরন, রক্তের গ্রুপ, ইস্যু ও মেয়াদ শেষের তারিখ, এবং জাতীয়তা।"}]}},"t01":{"en":{"title":"Speed and stopping distance","blocks":[{"text":"Always adjust your speed to the conditions so that you can stop in time. Speeding and failing to adjust speed to the conditions are major causes of road accidents."},{"text":"Stopping distance = reaction distance + braking distance. The usual reaction time is one second."},{"text":"Reaction distance (m) = (speed ÷ 10) × 3 · Braking distance (m) = (speed ÷ 10) × (speed ÷ 10) on a dry road."},{"table":[["Speed (km/h)","Reaction (m)","Braking (m)","Stopping (m)"],["30","9","9","18"],["50","15","25","40"],["60","18","36","54"],["80","24","64","88"],["100","30","100","130"],["120","36","144","180"]]},{"text":"Reaction distance gets longer with high speed, distraction and fatigue, and drugs, alcohol or medicines that cause drowsiness."},{"text":"Braking distance gets longer with speed, a heavy load, poor road conditions (sand, wet surface), and poor tyres or brakes."},{"text":"To reduce it: slow down, pay more attention, and rest your foot over the brake pedal without pressing."},{"text":"If your speed is just 10 km/h higher (from 50 to 60), you may hit at about 40 km/h instead of stopping, and the impact is like falling from a height of 6.5 metres without a seat belt."}]},"ur":{"title":"رفتار اور رکنے کا فاصلہ","blocks":[{"text":"اپنی رفتار ہمیشہ حالات کے مطابق رکھیں تاکہ آپ بروقت رک سکیں۔ تیز رفتاری اور اسے حالات کے مطابق نہ رکھنا ٹریفک حادثات کی ایک بڑی وجہ ہے۔"},{"text":"رکنے کا فاصلہ = ردِعمل کا فاصلہ + بریک کا فاصلہ۔ ردِعمل کا عام وقت ایک سیکنڈ ہے۔"},{"text":"ردِعمل = (رفتار ÷ 10) × 3 · بریک = (رفتار ÷ 10) × (رفتار ÷ 10) خشک سڑک پر۔"},{"table":[["رفتار (کلومیٹر فی گھنٹہ)","ردِعمل (میٹر)","بریک (میٹر)","رکنا (میٹر)"],["30","9","9","18"],["50","15","25","40"],["60","18","36","54"],["80","24","64","88"],["100","30","100","130"],["120","36","144","180"]]},{"text":"تیز رفتاری، توجہ بٹنے اور تھکاوٹ، اور منشیات، شراب یا غنودگی پیدا کرنے والی دواؤں سے ردِعمل کا فاصلہ بڑھ جاتا ہے۔"},{"text":"رفتار، بھاری بوجھ، خراب سڑک (ریت، گیلا پن)، اور خراب ٹائر یا بریک سے بریک کا فاصلہ بڑھ جاتا ہے۔"},{"text":"اسے کم کرنے کے لیے: رفتار کم کریں، توجہ بڑھائیں، اور پاؤں دبائے بغیر بریک کے اوپر رکھیں۔"},{"text":"اگر آپ کی رفتار صرف 10 کلومیٹر فی گھنٹہ زیادہ ہو (50 سے 60)، تو رکنے کے بجائے آپ تقریباً 40 کلومیٹر فی گھنٹہ کی رفتار سے ٹکرا سکتے ہیں، اور اس کا اثر سیٹ بیلٹ کے بغیر 6.5 میٹر کی بلندی سے گرنے جیسا ہے۔"}]},"hi":{"title":"गति और रुकने की दूरी","blocks":[{"text":"हमेशा अपनी गति हालात के अनुसार रखें ताकि आप समय पर रुक सकें। तेज़ गति और हालात के अनुसार गति न रखना सड़क दुर्घटनाओं का एक बड़ा कारण है।"},{"text":"रुकने की दूरी = प्रतिक्रिया दूरी + ब्रेक लगाने की दूरी। आम तौर पर प्रतिक्रिया का समय एक सेकंड होता है।"},{"text":"प्रतिक्रिया = (गति ÷ 10) × 3 · ब्रेक = (गति ÷ 10) × (गति ÷ 10), सूखी सड़क पर।"},{"table":[["गति (किमी/घंटा)","प्रतिक्रिया दूरी (मीटर)","ब्रेक दूरी (मीटर)","रुकने की दूरी (मीटर)"],["30","9","9","18"],["50","15","25","40"],["60","18","36","54"],["80","24","64","88"],["100","30","100","130"],["120","36","144","180"]]},{"text":"तेज़ गति, ध्यान भटकने और थकान, और नशीले पदार्थ, शराब या नींद लाने वाली दवाओं से प्रतिक्रिया दूरी बढ़ जाती है।"},{"text":"गति, भारी लोड, सड़क की खराब हालत (रेत, गीली सड़क), और खराब टायर या ब्रेक से ब्रेक लगाने की दूरी बढ़ जाती है।"},{"text":"इसे कम करने के लिए: गति कम करें, ज़्यादा ध्यान दें, और अपना पैर ब्रेक के ऊपर रखें, पर दबाएँ नहीं।"},{"text":"अगर आपकी गति सिर्फ़ 10 किमी/घंटा ज़्यादा हो (50 से 60), तो आप रुकने के बजाय लगभग 40 किमी/घंटा की गति से टकरा सकते हैं, और इसका असर बिना सीट बेल्ट के 6.5 मीटर की ऊँचाई से गिरने जैसा होता है।"}]},"bn":{"title":"গতি ও থামার দূরত্ব","blocks":[{"text":"সবসময় পরিস্থিতি অনুযায়ী গতি ঠিক রাখুন, যাতে সময়মতো থামতে পারেন। অতিরিক্ত গতি এবং পরিস্থিতি অনুযায়ী গতি ঠিক না রাখা সড়ক দুর্ঘটনার একটি প্রধান কারণ।"},{"text":"থামার দূরত্ব = প্রতিক্রিয়ার দূরত্ব + ব্রেক করার দূরত্ব। সাধারণত প্রতিক্রিয়ার সময় এক সেকেন্ড।"},{"text":"প্রতিক্রিয়া = (গতি ÷ 10) × 3 · ব্রেক = (গতি ÷ 10) × (গতি ÷ 10), শুকনো রাস্তায়।"},{"table":[["গতি (কিমি/ঘণ্টা)","প্রতিক্রিয়া (মিটার)","ব্রেক (মিটার)","থামা (মিটার)"],["30","9","9","18"],["50","15","25","40"],["60","18","36","54"],["80","24","64","88"],["100","30","100","130"],["120","36","144","180"]]},{"text":"বেশি গতি, অমনোযোগ ও ক্লান্তি, এবং মাদক, মদ বা ঘুম আনে এমন ওষুধে প্রতিক্রিয়ার দূরত্ব বেড়ে যায়।"},{"text":"গতি, ভারী বোঝা, রাস্তার খারাপ অবস্থা (বালু, ভেজা রাস্তা), এবং খারাপ টায়ার বা ব্রেকে ব্রেক করার দূরত্ব বেড়ে যায়।"},{"text":"এটি কমাতে: গতি কমান, মনোযোগ বাড়ান, এবং চাপ না দিয়ে ব্রেকের ওপর পা রাখুন।"},{"text":"আপনার গতি মাত্র 10 কিমি/ঘণ্টা বেশি হলে (50 থেকে 60), থামার বদলে আপনি প্রায় 40 কিমি/ঘণ্টা গতিতে ধাক্কা খেতে পারেন, আর এর আঘাত সিট বেল্ট ছাড়া 6.5 মিটার উঁচু থেকে পড়ে যাওয়ার মতো।"}]}},"t02":{"en":{"title":"Traffic accidents","blocks":[{"text":"Reasons for the high number of accidents: speeding, not following the rules, using a mobile phone and not wearing a seat belt, sudden lane changes, and the condition of the vehicle and the road."},{"text":"Minor accident: damage not exceeding 5,000 SAR or an injury that does not require hospital treatment. Major accident: deaths or serious injuries."},{"text":"Legal liability depends on the share of fault: 100%, 75%, 50% or 25%."},{"text":"In an accident with injuries: call the traffic police (993 / 911) and the Red Crescent (997). In an accident with damage only: use the Najm app and photograph the accident from all angles."},{"text":"Do not move the vehicles unless they block traffic or threaten safety, or the accident is minor and both parties agree."},{"text":"Leaving the accident scene without a reason counts as fleeing. The penalty can reach 2,000 SAR and/or 3 months in prison. Detention in accidents involving death or serious injury does not exceed 72 hours."}]},"ur":{"title":"ٹریفک حادثات","blocks":[{"text":"حادثات بڑھنے کی وجوہات: تیز رفتاری، قوانین کی پابندی نہ کرنا، موبائل فون کا استعمال اور سیٹ بیلٹ نہ باندھنا، اچانک لین تبدیل کرنا، اور گاڑی اور سڑک کی حالت۔"},{"text":"معمولی حادثہ: نقصان 5000 ریال سے زیادہ نہ ہو یا ایسی چوٹ جس کے لیے اسپتال جانے کی ضرورت نہ ہو۔ بڑا حادثہ: اموات یا شدید چوٹیں۔"},{"text":"قانونی ذمہ داری غلطی کے تناسب کے مطابق ہوتی ہے: 100%، 75%، 50% یا 25%۔"},{"text":"زخمیوں والے حادثے میں: ٹریفک پولیس (993 / 911) اور ہلال احمر (997) کو کال کریں۔ صرف نقصان والے حادثے میں: «نجم» ایپ استعمال کریں اور حادثے کی ہر زاویے سے تصویریں لیں۔"},{"text":"گاڑیوں کو اس وقت تک نہ ہٹائیں جب تک وہ ٹریفک میں رکاوٹ نہ بنیں یا حفاظت کے لیے خطرہ نہ ہوں، یا حادثہ معمولی ہو اور دونوں فریق متفق ہوں۔"},{"text":"بغیر وجہ حادثے کی جگہ چھوڑنا فرار شمار ہوتا ہے۔ سزا 2000 ریال اور/یا 3 ماہ قید تک ہو سکتی ہے۔ موت یا شدید چوٹ والے حادثات میں حراست 72 گھنٹے سے زیادہ نہیں ہوتی۔"}]},"hi":{"title":"सड़क दुर्घटनाएँ","blocks":[{"text":"दुर्घटनाएँ ज़्यादा होने के कारण: तेज़ गति, नियमों का पालन न करना, मोबाइल फ़ोन का इस्तेमाल और सीट बेल्ट न लगाना, अचानक लेन बदलना, और वाहन व सड़क की हालत।"},{"text":"छोटी दुर्घटना: 5,000 रियाल से ज़्यादा का नुकसान न हो, या ऐसी चोट जिसमें अस्पताल जाने की ज़रूरत न हो। बड़ी दुर्घटना: मौतें या गंभीर चोटें।"},{"text":"कानूनी ज़िम्मेदारी गलती के हिस्से के अनुसार तय होती है: 100%, 75%, 50% या 25%।"},{"text":"चोट वाली दुर्घटना में: ट्रैफिक पुलिस (993 / 911) और रेड क्रेसेंट (997) को फ़ोन करें। सिर्फ़ नुकसान वाली दुर्घटना में: नज्म ऐप का इस्तेमाल करें और दुर्घटना की हर तरफ़ से फ़ोटो लें।"},{"text":"वाहनों को तभी हटाएँ जब वे ट्रैफिक रोक रहे हों या सुरक्षा के लिए खतरा हों, या दुर्घटना छोटी हो और दोनों पक्ष सहमत हों।"},{"text":"बिना कारण दुर्घटना की जगह छोड़ना भागना माना जाता है। सज़ा 2,000 रियाल तक जुर्माना और/या 3 महीने की जेल तक हो सकती है। मौत या गंभीर चोट वाली दुर्घटनाओं में हिरासत 72 घंटे से ज़्यादा नहीं होती।"}]},"bn":{"title":"সড়ক দুর্ঘটনা","blocks":[{"text":"দুর্ঘটনা বেশি হওয়ার কারণ: অতিরিক্ত গতি, নিয়ম না মানা, মোবাইল ফোন ব্যবহার ও সিট বেল্ট না বাঁধা, হঠাৎ লেন পরিবর্তন, এবং গাড়ি ও রাস্তার অবস্থা।"},{"text":"ছোট দুর্ঘটনা: ক্ষতি 5,000 রিয়ালের বেশি নয়, অথবা এমন আঘাত যাতে হাসপাতালে যেতে হয় না। বড় দুর্ঘটনা: মৃত্যু বা গুরুতর আঘাত।"},{"text":"আইনগত দায় নির্ভর করে দোষের অংশের ওপর: 100%, 75%, 50% বা 25%।"},{"text":"যে দুর্ঘটনায় কেউ আহত হয়েছে: ট্রাফিক পুলিশ (993 / 911) এবং রেড ক্রিসেন্টে (997) ফোন করুন। যে দুর্ঘটনায় শুধু ক্ষয়ক্ষতি হয়েছে: নাজম অ্যাপ ব্যবহার করুন এবং সব দিক থেকে দুর্ঘটনার ছবি তুলুন।"},{"text":"গাড়ি সরাবেন না, যদি না সেগুলো যান চলাচলে বাধা দেয় বা নিরাপত্তার জন্য হুমকি হয়, অথবা দুর্ঘটনা ছোট হয় এবং উভয় পক্ষ রাজি থাকে।"},{"text":"কোনো কারণ ছাড়া দুর্ঘটনার স্থান ছেড়ে চলে যাওয়াকে পালানো ধরা হয়। শাস্তি 2,000 রিয়াল পর্যন্ত জরিমানা এবং/অথবা 3 মাস পর্যন্ত কারাদণ্ড হতে পারে। মৃত্যু বা গুরুতর আঘাতের দুর্ঘটনায় আটক রাখা 72 ঘণ্টার বেশি হয় না।"}]}},"t03":{"en":{"title":"Violations and fines","blocks":[{"table":[["Category","Fine (SAR)","Examples"],["1","100–150","Parking outside designated places, no valid insurance"],["2","150–300","Not using the indicator, not wearing a seat belt, not carrying the licence, not keeping a safe distance, reversing more than 20 m"],["3","300–500","Being distracted from the road, sudden braking, expired licence, not using a child seat"],["4","500–900","Not stopping at a \"Stop\" sign, right-of-way violation, phone in hand, driving in a tunnel without lights"],["5","1,000–2,000","Stopping on a railway line, driving without a front plate, overtaking where prohibited, not wearing a helmet"],["6","3,000–6,000","Running a red light, overtaking a school bus, driving against traffic, racing"],["7","5,000–10,000","Driving under the influence of alcohol or drugs, plates that do not belong to the vehicle"]]},{"text":"Speeding fines by how far over the limit you drive:"},{"table":[["Over the limit (km/h)","Roads up to 120 km/h (SAR)","140 km/h roads (SAR)"],["5–10","—","300–500"],["10–20","150–300","800–1,000"],["20–30","300–500","1,200–1,500"],["30–40","800–1,000","1,500–2,000"],["40–50","1,200–1,500","1,500–2,000"],["More than 50","1,500–2,000","1,500–2,000"]]},{"text":"Drifting (tafheet): first time, vehicle impounded for 15 days and a 20,000 SAR fine; second time, one month and 40,000; third time, vehicle confiscated and 60,000."},{"text":"The violator stays inside their vehicle until the traffic officer arrives. The minimum fine can be paid within 30 days; after that the maximum applies. Check and pay through Absher."}]},"ur":{"title":"خلاف ورزیاں اور جرمانے","blocks":[{"table":[["کیٹیگری","جرمانہ (ریال)","مثالیں"],["1","100–150","مقررہ جگہوں کے علاوہ پارکنگ، کارآمد انشورنس نہ ہونا"],["2","150–300","انڈیکیٹر استعمال نہ کرنا، سیٹ بیلٹ نہ باندھنا، لائسنس ساتھ نہ رکھنا، محفوظ فاصلہ کم رکھنا، 20 میٹر سے زیادہ ریورس کرنا"],["3","300–500","سڑک سے توجہ ہٹانا، اچانک بریک لگانا، میعاد ختم لائسنس، بچوں کی سیٹ استعمال نہ کرنا"],["4","500–900","«رکیں» کے نشان پر نہ رکنا، ترجیح کی خلاف ورزی، ہاتھ میں موبائل، سرنگ میں لائٹس کے بغیر چلانا"],["5","1000–2000","ریلوے لائن پر رکنا، اگلی نمبر پلیٹ کے بغیر چلانا، ممنوعہ اوورٹیک، ہیلمٹ نہ پہننا"],["6","3000–6000","سرخ سگنل توڑنا، اسکول بس کو اوورٹیک کرنا، الٹی سمت چلانا، ریس لگانا"],["7","5000–10000","نشہ آور چیز یا منشیات کے زیر اثر ڈرائیونگ، ایسی نمبر پلیٹیں جو گاڑی کی نہ ہوں"]]},{"text":"رفتار کی حد سے تجاوز پر جرمانے، حد سے جتنا زیادہ ہو:"},{"table":[["حد سے زیادہ (کلومیٹر فی گھنٹہ)","120 کلومیٹر فی گھنٹہ تک کی سڑکیں (ریال)","140 کلومیٹر فی گھنٹہ کی سڑکیں (ریال)"],["5–10","—","300–500"],["10–20","150–300","800–1000"],["20–30","300–500","1200–1500"],["30–40","800–1000","1500–2000"],["40–50","1200–1500","1500–2000"],["50 سے زیادہ","1500–2000","1500–2000"]]},{"text":"ڈرفٹنگ (تفحیط): پہلی بار گاڑی 15 دن کے لیے ضبط اور 20 ہزار ریال جرمانہ، دوسری بار ایک مہینہ اور 40 ہزار، تیسری بار گاڑی کی ضبطی اور 60 ہزار۔"},{"text":"خلاف ورزی کرنے والا ٹریفک اہلکار کے پہنچنے تک اپنی گاڑی میں رہے۔ کم از کم جرمانہ 30 دن کے اندر ادا کیا جا سکتا ہے، اس کے بعد زیادہ سے زیادہ جرمانہ لازم ہوگا۔ معلومات اور ادائیگی ابشر کے ذریعے۔"}]},"hi":{"title":"उल्लंघन और जुर्माने","blocks":[{"table":[["श्रेणी","जुर्माना (रियाल)","उदाहरण"],["1","100–150","तय जगहों के बाहर पार्किंग, वैध बीमा न होना"],["2","150–300","इंडिकेटर न देना, सीट बेल्ट न लगाना, लाइसेंस साथ न रखना, सुरक्षित दूरी कम रखना, 20 मीटर से ज़्यादा रिवर्स करना"],["3","300–500","सड़क से ध्यान हटना, अचानक ब्रेक लगाना, लाइसेंस की अवधि खत्म होना, बच्चे की सीट का इस्तेमाल न करना"],["4","500–900","\"रुकें\" (STOP) संकेत पर न रुकना, रास्ता देने के नियम का उल्लंघन, हाथ में मोबाइल, बिना लाइट के सुरंग में गाड़ी चलाना"],["5","1000–2000","रेलवे लाइन पर रुकना, आगे की नंबर प्लेट के बिना गाड़ी चलाना, मना की गई जगह पर ओवरटेक करना, हेलमेट न पहनना"],["6","3000–6000","रेड लाइट तोड़ना, स्कूल बस को ओवरटेक करना, उल्टी दिशा में गाड़ी चलाना, रेस लगाना"],["7","5000–10000","शराब या नशीले पदार्थ के असर में गाड़ी चलाना, ऐसी नंबर प्लेट जो उस वाहन की न हो"]]},{"text":"गति सीमा से ज़्यादा चलाने पर जुर्माना, सीमा से कितना ज़्यादा है उसके अनुसार:"},{"table":[["सीमा से ज़्यादा (किमी/घंटा)","120 किमी/घंटा तक की सड़कें (रियाल)","140 किमी/घंटा की सड़कें (रियाल)"],["5–10","—","300–500"],["10–20","150–300","800–1000"],["20–30","300–500","1200–1500"],["30–40","800–1000","1500–2000"],["40–50","1200–1500","1500–2000"],["50 से ज़्यादा","1500–2000","1500–2000"]]},{"text":"ड्रिफ्टिंग (तफ़हीत): पहली बार, वाहन 15 दिन के लिए ज़ब्त और 20,000 रियाल जुर्माना; दूसरी बार, एक महीना और 40,000; तीसरी बार, वाहन हमेशा के लिए ज़ब्त और 60,000।"},{"text":"उल्लंघन करने वाला ट्रैफिक पुलिसकर्मी के आने तक अपने वाहन के अंदर ही रहे। कम से कम जुर्माना 30 दिनों के अंदर भरा जा सकता है; उसके बाद ज़्यादा से ज़्यादा जुर्माना देना होगा। जानकारी और भुगतान अबशिर के ज़रिए करें।"}]},"bn":{"title":"লঙ্ঘন ও জরিমানা","blocks":[{"table":[["শ্রেণি","জরিমানা (রিয়াল)","উদাহরণ"],["1","100–150","নির্ধারিত জায়গার বাইরে পার্কিং, বৈধ বিমা না থাকা"],["2","150–300","ইন্ডিকেটর ব্যবহার না করা, সিট বেল্ট না বাঁধা, লাইসেন্স সঙ্গে না রাখা, নিরাপদ দূরত্ব কম রাখা, 20 মিটারের বেশি রিভার্স করা"],["3","300–500","রাস্তা থেকে মনোযোগ সরে যাওয়া, হঠাৎ ব্রেক করা, মেয়াদোত্তীর্ণ লাইসেন্স, শিশুর সিট ব্যবহার না করা"],["4","500–900","\"থামুন\" (STOP) চিহ্নে না থামা, পথ ছেড়ে দেওয়ার নিয়ম লঙ্ঘন, হাতে মোবাইল, আলো ছাড়া সুড়ঙ্গে/টানেলে গাড়ি চালানো"],["5","1000–2000","রেললাইনের ওপর থামা, সামনের নম্বর প্লেট ছাড়া গাড়ি চালানো, নিষিদ্ধ জায়গায় ওভারটেক করা, হেলমেট না পরা"],["6","3000–6000","লাল বাতি অমান্য করা, স্কুল বাস ওভারটেক করা, উল্টো দিকে গাড়ি চালানো, রেস করা"],["7","5000–10000","মদ বা মাদকের প্রভাবে গাড়ি চালানো, গাড়ির নয় এমন নম্বর প্লেট"]]},{"text":"গতিসীমা অতিক্রমের জরিমানা, সীমার চেয়ে কত বেশি তার ওপর নির্ভর করে:"},{"table":[["সীমার চেয়ে বেশি (কিমি/ঘণ্টা)","120 কিমি/ঘণ্টা পর্যন্ত রাস্তা (রিয়াল)","140 কিমি/ঘণ্টার রাস্তা (রিয়াল)"],["5–10","—","300–500"],["10–20","150–300","800–1000"],["20–30","300–500","1200–1500"],["30–40","800–1000","1500–2000"],["40–50","1200–1500","1500–2000"],["50-এর বেশি","1500–2000","1500–2000"]]},{"text":"ড্রিফটিং (তাফহীত): প্রথমবার 15 দিনের জন্য গাড়ি আটক ও 20,000 রিয়াল জরিমানা; দ্বিতীয়বার এক মাস ও 40,000; তৃতীয়বার গাড়ি বাজেয়াপ্ত ও 60,000।"},{"text":"লঙ্ঘনকারী ট্রাফিক পুলিশ না আসা পর্যন্ত নিজের গাড়ির ভেতরেই থাকবেন। সর্বনিম্ন জরিমানা 30 দিনের মধ্যে দেওয়া যায়; এরপর সর্বোচ্চ জরিমানা দিতে হয়। আবশিরের মাধ্যমে খোঁজ নিন ও পরিশোধ করুন।"}]}},"t04":{"en":{"title":"Violation points and licence suspension","blocks":[{"table":[["Points","Violation"],["24","Driving under the influence of alcohol or drugs"],["24","Drifting (tafheet)"],["12","Not stopping at a red light"],["12","Driving against the direction of traffic"],["8","Reckless driving between vehicles"],["8","Not obeying a traffic officer's instructions"],["8","Driving a vehicle without brakes or lights"],["6","Not coming to a complete stop at a \"Stop\" sign"],["6","Not respecting the right of way"],["6","Exceeding the speed limit by more than 25 km/h"],["6","Not giving way at a roundabout"],["6","Overtaking in prohibited places"],["6","Stopping on railway tracks"],["4","Exceeding the speed limit by no more than 25 km/h"],["4","Driving in lanes not designated for the vehicle"],["4","Overtaking a school bus while students are getting on or off"],["4","Not covering or securing loads"],["4","Modifying the body without official procedures"],["2","Not wearing a seat belt"],["2","Using a hand-held mobile phone"],["2","Not wearing a helmet on a motorcycle"]]},{"text":"On reaching 24 points the licence is suspended: the first time in a Hijri year for 3 months, the second for 6 months, the third for one year, and the fourth is permanent revocation."},{"text":"Driving while the licence is suspended is referred to court, and the driver may be required to take a 15-day rehabilitation programme. After permanent revocation, the driver can apply for a new licence after one year, with a one-month rehabilitation programme and passing both tests."}]},"ur":{"title":"خلاف ورزی کے پوائنٹس اور لائسنس کی معطلی","blocks":[{"table":[["پوائنٹس","خلاف ورزی"],["24","نشہ آور چیز یا منشیات کے زیر اثر ڈرائیونگ"],["24","ڈرفٹنگ (تفحیط)"],["12","سرخ سگنل پر نہ رکنا"],["12","ٹریفک کی الٹی سمت میں ڈرائیونگ"],["8","گاڑیوں کے درمیان لاپروائی سے ڈرائیونگ"],["8","ٹریفک اہلکار کی ہدایات پر عمل نہ کرنا"],["8","بریک یا لائٹس کے بغیر گاڑی چلانا"],["6","«رکیں» کے نشان پر مکمل طور پر نہ رکنا"],["6","ترجیح کا احترام نہ کرنا"],["6","رفتار کی حد سے 25 کلومیٹر فی گھنٹہ سے زیادہ تجاوز"],["6","گول چکر میں ترجیح نہ دینا"],["6","ممنوعہ جگہوں پر اوورٹیک کرنا"],["6","ریلوے لائن پر رکنا"],["4","رفتار کی حد سے 25 کلومیٹر فی گھنٹہ تک تجاوز"],["4","غیر مخصوص لین میں ڈرائیونگ"],["4","سواریاں چڑھاتے وقت اسکول بس کو اوورٹیک کرنا"],["4","سامان کو نہ ڈھانپنا یا نہ باندھنا"],["4","قانونی کارروائی کے بغیر گاڑی کے ڈھانچے میں تبدیلی"],["2","سیٹ بیلٹ نہ باندھنا"],["2","ہاتھ میں موبائل فون استعمال کرنا"],["2","موٹر سائیکل پر ہیلمٹ نہ پہننا"]]},{"text":"24 پوائنٹس پورے ہونے پر لائسنس معطل کر دیا جاتا ہے: ہجری سال میں پہلی بار 3 ماہ، دوسری بار 6 ماہ، تیسری بار ایک سال، اور چوتھی بار مستقل منسوخی۔"},{"text":"لائسنس معطلی کے دوران ڈرائیونگ کا معاملہ عدالت بھیجا جاتا ہے، اور ڈرائیور کو 15 دن کا بحالی پروگرام لازمی کیا جا سکتا ہے۔ مستقل منسوخی کے بعد ایک سال بعد نئے لائسنس کے لیے درخواست دی جا سکتی ہے، ایک ماہ کے بحالی پروگرام اور دونوں ٹیسٹ پاس کرنے کے ساتھ۔"}]},"hi":{"title":"उल्लंघन पॉइंट और लाइसेंस निलंबन","blocks":[{"table":[["पॉइंट","उल्लंघन"],["24","शराब या नशीले पदार्थ के असर में गाड़ी चलाना"],["24","ड्रिफ्टिंग (तफ़हीत)"],["12","रेड लाइट पर न रुकना"],["12","ट्रैफिक की उल्टी दिशा में गाड़ी चलाना"],["8","वाहनों के बीच लापरवाही से गाड़ी चलाना"],["8","ट्रैफिक पुलिसकर्मी के निर्देश न मानना"],["8","बिना ब्रेक या लाइट वाला वाहन चलाना"],["6","\"रुकें\" (STOP) संकेत पर पूरी तरह न रुकना"],["6","पहले जाने के हक़ (राइट ऑफ़ वे) का पालन न करना"],["6","गति सीमा से 25 किमी/घंटा से ज़्यादा तेज़ चलाना"],["6","गोल चक्कर पर रास्ता न देना"],["6","मना की गई जगहों पर ओवरटेक करना"],["6","रेलवे ट्रैक पर रुकना"],["4","गति सीमा से 25 किमी/घंटा तक ज़्यादा तेज़ चलाना"],["4","वाहन के लिए तय न की गई लेन में गाड़ी चलाना"],["4","सवारी चढ़ाते समय स्कूल बस को ओवरटेक करना"],["4","लोड को न ढकना या न बाँधना"],["4","कानूनी प्रक्रिया के बिना वाहन की बॉडी में बदलाव करना"],["2","सीट बेल्ट न लगाना"],["2","हाथ में पकड़कर मोबाइल फ़ोन इस्तेमाल करना"],["2","मोटरसाइकिल पर हेलमेट न पहनना"]]},{"text":"24 पॉइंट पूरे होने पर लाइसेंस निलंबित कर दिया जाता है: एक हिजरी साल में पहली बार 3 महीने के लिए, दूसरी बार 6 महीने, तीसरी बार एक साल, और चौथी बार हमेशा के लिए रद्द।"},{"text":"लाइसेंस निलंबित रहते हुए गाड़ी चलाने पर मामला अदालत भेजा जाता है, और ड्राइवर को 15 दिन का पुनर्वास (रिहैबिलिटेशन) कार्यक्रम करना पड़ सकता है। हमेशा के लिए रद्द होने के बाद, ड्राइवर एक साल बाद नए लाइसेंस के लिए आवेदन कर सकता है, जिसमें एक महीने का पुनर्वास कार्यक्रम और दोनों टेस्ट पास करना ज़रूरी है।"}]},"bn":{"title":"লঙ্ঘনের পয়েন্ট ও লাইসেন্স স্থগিতকরণ","blocks":[{"table":[["পয়েন্ট","লঙ্ঘন"],["24","মদ বা মাদকের প্রভাবে গাড়ি চালানো"],["24","ড্রিফটিং (তাফহীত)"],["12","লাল বাতিতে না থামা"],["12","যান চলাচলের উল্টো দিকে গাড়ি চালানো"],["8","গাড়িগুলোর মাঝ দিয়ে বেপরোয়াভাবে গাড়ি চালানো"],["8","ট্রাফিক পুলিশের নির্দেশ না মানা"],["8","ব্রেক বা বাতি ছাড়া গাড়ি চালানো"],["6","\"থামুন\" (STOP) চিহ্নে পুরোপুরি না থামা"],["6","অগ্রাধিকার (পথ ছেড়ে দেওয়ার নিয়ম) না মানা"],["6","গতিসীমার চেয়ে 25 কিমি/ঘণ্টার বেশি গতিতে চালানো"],["6","গোলচত্বরে পথ ছেড়ে না দেওয়া"],["6","নিষিদ্ধ জায়গায় ওভারটেক করা"],["6","রেললাইনের ওপর থামা"],["4","গতিসীমার চেয়ে সর্বোচ্চ 25 কিমি/ঘণ্টা বেশি গতিতে চালানো"],["4","গাড়ির জন্য নির্ধারিত নয় এমন লেনে চালানো"],["4","যাত্রী ওঠানোর সময় স্কুল বাস ওভারটেক করা"],["4","মালামাল না ঢাকা বা না বাঁধা"],["4","আইনি প্রক্রিয়া ছাড়া গাড়ির বডি পরিবর্তন করা"],["2","সিট বেল্ট না বাঁধা"],["2","হাতে ধরে মোবাইল ফোন ব্যবহার করা"],["2","মোটরসাইকেলে হেলমেট না পরা"]]},{"text":"24 পয়েন্ট হলে লাইসেন্স স্থগিত করা হয়: এক হিজরি বছরে প্রথমবার 3 মাসের জন্য, দ্বিতীয়বার 6 মাস, তৃতীয়বার এক বছর, আর চতুর্থবার স্থায়ীভাবে বাতিল।"},{"text":"লাইসেন্স স্থগিত থাকা অবস্থায় গাড়ি চালালে বিষয়টি আদালতে পাঠানো হয়, এবং চালককে 15 দিনের পুনর্বাসন কর্মসূচিতে অংশ নিতে হতে পারে। স্থায়ীভাবে বাতিলের পর, চালক এক বছর পর নতুন লাইসেন্সের জন্য আবেদন করতে পারেন, সঙ্গে এক মাসের পুনর্বাসন কর্মসূচি এবং দুটি পরীক্ষাতেই পাস করতে হবে।"}]}},"t05":{"en":{"title":"Parts of the road and guide signs","blocks":[{"text":"A main road is entered and exited through entrances and exits, and a service road serves the adjacent properties. The traffic island (median) separates the two directions, and the merging lane lets you join the road's traffic."},{"text":"Guide signs: blue with white letters (cities and villages outside the city), green (streets and districts inside cities), white with black letters (important facilities such as airports), brown (farms, resorts, museums and religious places)."},{"text":"Temporary work zone signs have the same shapes but are yellow with a red border."}]},"ur":{"title":"سڑک کے حصے اور رہنمائی کے نشانات","blocks":[{"text":"مین روڈ میں داخلے اور اس سے نکلنے کے لیے داخلی اور خارجی راستے استعمال ہوتے ہیں، اور سروس روڈ آس پاس کی جائیدادوں کے لیے ہوتی ہے۔ ٹریفک آئی لینڈ (درمیانی پٹی) دونوں سمتوں کو الگ کرتی ہے، اور ضم ہونے والی لین سڑک کی ٹریفک میں شامل ہونے کی اجازت دیتی ہے۔"},{"text":"رہنمائی کے بورڈ: نیلے رنگ پر سفید حروف (شہر سے باہر کے شہر اور گاؤں)، سبز (شہروں کے اندر سڑکیں اور محلے)، سفید رنگ پر سیاہ حروف (اہم سہولیات جیسے ہوائی اڈے)، بھورے (فارم، ریزورٹ، عجائب گھر اور مذہبی مقامات)۔"},{"text":"عارضی کام کے علاقوں کے نشانات انہی شکلوں کے ہوتے ہیں لیکن پیلے رنگ کے اور سرخ کنارے کے ساتھ۔"}]},"hi":{"title":"सड़क के हिस्से और मार्गदर्शन संकेत","blocks":[{"text":"मुख्य सड़क पर प्रवेश और निकास के रास्तों से आया-जाया जाता है, और सर्विस रोड आसपास की संपत्तियों के काम आती है। ट्रैफिक आइलैंड (डिवाइडर) दोनों दिशाओं को अलग करता है, और मर्जिंग लेन से आप सड़क के ट्रैफिक में शामिल हो सकते हैं।"},{"text":"मार्गदर्शन बोर्ड: नीले रंग पर सफेद अक्षर (शहर से बाहर के शहरों और गाँवों के लिए), हरे (शहरों के अंदर की सड़कें और मोहल्ले), सफेद पर काले अक्षर (हवाई अड्डे जैसी ज़रूरी सुविधाएँ), भूरे (खेत, रिज़ॉर्ट, संग्रहालय और धार्मिक स्थान)।"},{"text":"अस्थायी कार्य क्षेत्र के संकेत उन्हीं आकारों के होते हैं, लेकिन पीले रंग के और लाल किनारे वाले।"}]},"bn":{"title":"রাস্তার অংশ ও নির্দেশক চিহ্ন","blocks":[{"text":"প্রধান সড়কে প্রবেশপথ ও বহির্গমন পথ দিয়ে ঢোকা ও বের হওয়া যায়, আর সার্ভিস রোড আশেপাশের সম্পত্তির কাজে লাগে। ট্রাফিক আইল্যান্ড (ডিভাইডার) দুই দিককে আলাদা করে, আর মার্জিং লেন দিয়ে সড়কের যানবাহনের সাথে যোগ দেওয়া যায়।"},{"text":"নির্দেশক বোর্ড: নীলের উপর সাদা অক্ষর (শহরের বাইরে, অন্য শহর ও গ্রামের দিক), সবুজ (শহরের ভেতরের রাস্তা ও এলাকা), সাদার উপর কালো অক্ষর (বিমানবন্দরের মতো গুরুত্বপূর্ণ স্থাপনা), বাদামি (খামার, রিসোর্ট, জাদুঘর ও ধর্মীয় স্থান)।"},{"text":"অস্থায়ী কাজের এলাকার চিহ্নগুলো একই আকারের, তবে হলুদ রঙের এবং লাল বর্ডারযুক্ত।"}]}},"t06":{"en":{"title":"Road users and behaviour","blocks":[{"text":"Rules of behaviour: drive safely, respectfully, cautiously and lawfully, and obey traffic officers' orders even if they contradict the usual rules (e.g. a green light while a traffic officer orders you to stop)."},{"text":"Pedestrians: a steady green allows crossing, a flashing green means red is about to come so the road must be cleared, and red prohibits crossing. At pedestrian crossings, reduce speed, be ready to stop and do not obstruct anyone who has started crossing."},{"text":"Emergency vehicles: give way immediately, do not follow them closer than 50 m, do not pull out of parking spaces before they pass, and clear intersections."},{"text":"School buses: they stop for students to get on and off, and overtaking them while they are stopped is prohibited."},{"text":"Official motorcades: give way to them and do not cut through them."},{"text":"Assess the people around you by age, attentiveness and intention. Children act spontaneously and do not judge danger, and elderly people may become confused and have poor hearing or eyesight. If you are not sure, make eye contact."}]},"ur":{"title":"سڑک استعمال کرنے والے اور رویہ","blocks":[{"text":"رویے کے اصول: محفوظ، باادب، محتاط اور قانونی ڈرائیونگ کریں، اور ٹریفک اہلکار کے احکامات پر عمل کریں چاہے وہ عام اصولوں کے خلاف ہوں (جیسے سبز سگنل ہو اور ٹریفک اہلکار آپ کو رکنے کا حکم دے)۔"},{"text":"پیدل چلنے والے: مسلسل سبز بتی سڑک پار کرنے کی اجازت دیتی ہے، جلتی بجھتی سبز بتی کا مطلب ہے کہ سرخ بتی قریب ہے اس لیے سڑک خالی کی جائے، اور سرخ بتی پار کرنے سے روکتی ہے۔ پیدل چلنے والوں کی گزرگاہ پر رفتار کم کریں، رکنے کے لیے تیار رہیں اور جس نے سڑک پار کرنا شروع کر دیا ہو اس کے راستے میں رکاوٹ نہ بنیں۔"},{"text":"ایمرجنسی گاڑیاں: فوراً راستہ دیں، ان کے پیچھے 50 میٹر سے کم فاصلے پر گاڑی نہ چلائیں، ان کے گزرنے سے پہلے پارکنگ سے باہر نہ نکلیں، اور چوراہے خالی کریں۔"},{"text":"اسکول بسیں: طلبہ کے چڑھنے اور اترنے کے لیے رکتی ہیں، اور رکی ہوئی اسکول بس کو اوورٹیک کرنا منع ہے۔"},{"text":"سرکاری قافلے: انہیں راستہ دیں اور ان کے بیچ سے نہ گزریں۔"},{"text":"اپنے اردگرد کے لوگوں کا اندازہ ان کی عمر، توجہ اور ارادے کے مطابق لگائیں۔ بچے بے ساختہ حرکت کرتے ہیں اور خطرے کا اندازہ نہیں لگاتے، اور بزرگ گھبرا سکتے ہیں اور انہیں کم سنائی یا کم دکھائی دے سکتا ہے۔ اگر آپ کو یقین نہ ہو تو آنکھوں سے رابطہ کریں۔"}]},"hi":{"title":"सड़क का इस्तेमाल करने वाले और व्यवहार","blocks":[{"text":"व्यवहार के नियम: सुरक्षित, सम्मानजनक, सावधान और कानून के अनुसार गाड़ी चलाएँ, और ट्रैफिक पुलिस के आदेश मानें, भले ही वे सामान्य नियमों के खिलाफ हों (जैसे हरी बत्ती हो और ट्रैफिक पुलिसकर्मी आपको रुकने का आदेश दे)।"},{"text":"पैदल यात्री: लगातार जलती हरी बत्ती पर पार करने की अनुमति है, टिमटिमाती हरी बत्ती का मतलब है कि लाल बत्ती होने वाली है, इसलिए सड़क खाली करनी है, और लाल बत्ती पर पार करना मना है। पैदल यात्री क्रॉसिंग पर गति कम करें, रुकने के लिए तैयार रहें और जो पार करना शुरू कर चुका है उसे न रोकें।"},{"text":"आपातकालीन वाहन: तुरंत रास्ता दें, उनके पीछे 50 मीटर से कम दूरी पर गाड़ी न चलाएँ, उनके गुज़रने से पहले पार्किंग से बाहर न निकलें, और चौराहे खाली करें।"},{"text":"स्कूल बसें: ये छात्रों के चढ़ने और उतरने के लिए रुकती हैं, और रुकी होने पर इन्हें ओवरटेक करना मना है।"},{"text":"सरकारी काफिले: इन्हें रास्ता दें और इनके बीच से न गुज़रें।"},{"text":"अपने आसपास के लोगों को उनकी उम्र, ध्यान और इरादे के आधार पर परखें। बच्चे अचानक कुछ भी कर देते हैं और खतरे को नहीं समझते, और बुज़ुर्ग घबरा सकते हैं और उन्हें कम सुनाई या कम दिखाई दे सकता है। अगर आपको पक्का न हो, तो आँखों से संपर्क करें।"}]},"bn":{"title":"সড়ক ব্যবহারকারী ও আচরণ","blocks":[{"text":"আচরণের নিয়ম: নিরাপদে, সম্মানের সাথে, সাবধানে ও আইন মেনে গাড়ি চালান, এবং ট্রাফিক পুলিশের আদেশ মানুন, যদিও তা সাধারণ নিয়মের বিপরীত হয় (যেমন সবুজ বাতি জ্বলছে কিন্তু ট্রাফিক পুলিশ আপনাকে থামতে বলছে)।"},{"text":"পথচারী: একটানা সবুজ বাতিতে পার হওয়া যায়, মিটমিট করা সবুজ বাতি মানে লাল বাতি আসছে, তাই রাস্তা খালি করতে হবে, আর লাল বাতিতে পার হওয়া নিষেধ। পথচারী পারাপারে গতি কমান, থামার জন্য প্রস্তুত থাকুন এবং যে পার হওয়া শুরু করেছে তাকে বাধা দেবেন না।"},{"text":"জরুরি যানবাহন: সাথে সাথে পথ ছেড়ে দিন, এগুলোর পেছনে 50 মিটারের কম দূরত্বে গাড়ি চালাবেন না, এগুলো চলে যাওয়ার আগে পার্কিং থেকে বের হবেন না, এবং মোড় খালি করে দিন।"},{"text":"স্কুল বাস: ছাত্রছাত্রীদের ওঠা-নামার জন্য থামে, এবং থেমে থাকা অবস্থায় এগুলোকে ওভারটেক করা নিষেধ।"},{"text":"সরকারি গাড়িবহর: এগুলোকে পথ ছেড়ে দিন এবং এগুলোর মাঝখান দিয়ে যাবেন না।"},{"text":"আশেপাশের মানুষকে বয়স, মনোযোগ ও উদ্দেশ্য অনুযায়ী বুঝে নিন। শিশুরা হঠাৎ কিছু করে বসে এবং বিপদ বোঝে না, আর বয়স্করা বিভ্রান্ত হতে পারেন এবং কম শুনতে বা কম দেখতে পারেন। নিশ্চিত না হলে চোখে চোখ রেখে যোগাযোগ করুন।"}]}},"t07":{"en":{"title":"Driver obligations and prohibitions","blocks":[{"text":"Do not drive while injured, ill, exhausted, distracted or agitated, or under the influence of alcohol, drugs or medication (read the medicine leaflet)."},{"text":"Before driving: clean the windows, lights and mirrors; check the tyres, lights and brakes; adjust your seating position and mirrors, and fasten your seat belt."},{"text":"While driving: stay on the paved part of the road, in the appropriate lane and within the permitted speed, and signal before turning."},{"text":"Prohibited: hazard lights except in emergencies, switching off the engine while moving, noise, curtains and advertisements on the vehicle, letting the vehicle roll, carrying people outside their seats, washing the vehicle on a public road, throwing litter, and taking part in processions without permission."},{"text":"In case of a breakdown: clear the road and secure the vehicle. By day, place a warning triangle at the stopping distance; at night, add red lights."},{"text":"When leaving the vehicle: switch off the engine, remove the key and lock the vehicle, and open the doors carefully on the kerb side."}]},"ur":{"title":"ڈرائیور کی ذمہ داریاں اور ممنوعات","blocks":[{"text":"زخمی، بیمار، بہت تھکے ہوئے، توجہ بٹی ہوئی یا غصے کی حالت میں گاڑی نہ چلائیں، اور نہ ہی شراب، منشیات یا دوا کے اثر میں (دوا کا پرچہ پڑھیں)۔"},{"text":"ڈرائیونگ سے پہلے: کھڑکیاں، لائٹس اور شیشے صاف کریں، ٹائر، لائٹس اور بریک چیک کریں، بیٹھنے کی پوزیشن اور شیشے درست کریں اور سیٹ بیلٹ باندھیں۔"},{"text":"ڈرائیونگ کے دوران: سڑک کے پکے حصے پر، مناسب لین میں اور مقررہ رفتار کے اندر چلیں، اور مڑنے سے پہلے انڈیکیٹر دیں۔"},{"text":"ممنوعات: ایمرجنسی کے علاوہ ہیزرڈ لائٹس، چلتے ہوئے انجن بند کرنا، شور، گاڑی پر پردے اور اشتہارات، گاڑی کو لڑھکنے دینا، لوگوں کو سیٹوں کے علاوہ جگہ پر بٹھا کر لے جانا، عام سڑک پر گاڑی دھونا، کچرا پھینکنا، اور اجازت کے بغیر جلوسوں میں شامل ہونا۔"},{"text":"گاڑی خراب ہونے پر: سڑک خالی کریں اور گاڑی کو محفوظ کریں۔ دن میں رکنے کے فاصلے پر وارننگ ٹرائینگل رکھیں، اور رات میں سرخ لائٹس بھی لگائیں۔"},{"text":"گاڑی چھوڑتے وقت: انجن بند کریں، چابی نکالیں اور گاڑی لاک کریں، اور فٹ پاتھ کی طرف سے دروازے احتیاط سے کھولیں۔"}]},"hi":{"title":"ड्राइवर की ज़िम्मेदारियाँ और मनाही","blocks":[{"text":"घायल, बीमार, बहुत थके हुए, ध्यान भटका हुआ या गुस्से/उत्तेजना में होने पर गाड़ी न चलाएँ, और न ही शराब, नशीले पदार्थ या दवा के असर में (दवा के साथ आया पर्चा पढ़ें)।"},{"text":"गाड़ी चलाने से पहले: खिड़कियाँ, लाइटें और शीशे साफ़ करें, टायर, लाइटें और ब्रेक जाँचें, बैठने की स्थिति और शीशे ठीक करें और सीट बेल्ट बाँधें।"},{"text":"गाड़ी चलाते समय: सड़क के पक्के हिस्से पर, सही लेन में और अनुमत गति के अंदर चलें, और मुड़ने से पहले इंडिकेटर दें।"},{"text":"मना है: आपातकाल के अलावा हैज़र्ड लाइट जलाना, चलते समय इंजन बंद करना, शोर करना, गाड़ी पर पर्दे और विज्ञापन लगाना, गाड़ी को अपने-आप लुढ़कने देना, लोगों को सीट के बाहर ले जाना, सार्वजनिक सड़क पर गाड़ी धोना, कचरा फेंकना, बिना अनुमति के जुलूस में शामिल होना।"},{"text":"गाड़ी खराब होने पर: सड़क खाली करें और गाड़ी को सुरक्षित करें। दिन में रुकने की दूरी पर चेतावनी त्रिकोण (वार्निंग ट्रायंगल) रखें, और रात में लाल लाइटें भी लगाएँ।"},{"text":"गाड़ी छोड़ते समय: इंजन बंद करें, चाबी निकालें और गाड़ी लॉक करें, और फुटपाथ की तरफ़ से दरवाज़े सावधानी से खोलें।"}]},"bn":{"title":"চালকের দায়িত্ব ও নিষেধাজ্ঞা","blocks":[{"text":"আহত, অসুস্থ, খুব ক্লান্ত, অমনোযোগী বা উত্তেজিত অবস্থায় গাড়ি চালাবেন না, এবং মদ, মাদক বা ওষুধের প্রভাবেও না (ওষুধের লিফলেট পড়ুন)।"},{"text":"গাড়ি চালানোর আগে: জানালা, লাইট ও আয়না পরিষ্কার করুন, টায়ার, লাইট ও ব্রেক পরীক্ষা করুন, বসার অবস্থান ও আয়না ঠিক করুন এবং সিট বেল্ট বাঁধুন।"},{"text":"গাড়ি চালানোর সময়: রাস্তার পাকা অংশে, সঠিক লেনে ও অনুমোদিত গতির মধ্যে চালান, এবং মোড় নেওয়ার আগে ইন্ডিকেটর দিন।"},{"text":"নিষিদ্ধ: জরুরি অবস্থা ছাড়া হ্যাজার্ড লাইট জ্বালানো, চলার সময় ইঞ্জিন বন্ধ করা, শব্দদূষণ, গাড়িতে পর্দা ও বিজ্ঞাপন লাগানো, গাড়িকে নিজে নিজে গড়িয়ে যেতে দেওয়া, মানুষকে সিটের বাইরে বহন করা, পাবলিক রাস্তায় গাড়ি ধোয়া, ময়লা ফেলা, অনুমতি ছাড়া শোভাযাত্রায় অংশ নেওয়া।"},{"text":"গাড়ি বিকল হলে: রাস্তা খালি করুন এবং গাড়ি নিরাপদ করুন। দিনে থামার দূরত্বে একটি সতর্কতা ত্রিভুজ (ওয়ার্নিং ট্রায়াঙ্গেল) রাখুন, আর রাতে লাল বাতিও যোগ করুন।"},{"text":"গাড়ি ছেড়ে যাওয়ার সময়: ইঞ্জিন বন্ধ করুন, চাবি খুলে নিন ও গাড়ি লক করুন, এবং ফুটপাতের দিক থেকে সাবধানে দরজা খুলুন।"}]}},"t08":{"en":{"title":"Carrying passengers and seat belts","blocks":[{"text":"Passengers may only be carried in vehicles designed for them; it is prohibited to carry them in the vehicle's rear cargo bed, on any external part, or in trucks."},{"text":"Seat belts are mandatory for the driver and all passengers, and the driver must remind passengers. Exemptions are for health reasons with medical proof and official permission, or because of body size."},{"text":"Children under 12 need a booster seat so that the belt sits below the shoulder. A child under 10 may not sit in the front seat unless there are no rear seats (and with a suitable child seat)."},{"text":"Leaving children under 10 in the vehicle without an adult is a violation."}]},"ur":{"title":"مسافروں کو لے جانا اور سیٹ بیلٹ","blocks":[{"text":"مسافروں کو صرف ان کے لیے مخصوص گاڑیوں میں لے جانے کی اجازت ہے، اور گاڑی کے پچھلے کھلے حصے، کسی بیرونی حصے یا ٹرکوں میں لے جانا منع ہے۔"},{"text":"سیٹ بیلٹ ڈرائیور اور تمام مسافروں کے لیے لازمی ہے، اور ڈرائیور کو مسافروں کو یاد دلانا چاہیے۔ طبی ثبوت اور سرکاری اجازت کے ساتھ صحت کی وجوہات پر، یا جسامت کی وجہ سے، چھوٹ ہے۔"},{"text":"12 سال سے کم عمر بچوں کو بوسٹر سیٹ کی ضرورت ہے تاکہ بیلٹ کندھے سے نیچے رہے۔ 10 سال سے کم عمر بچہ اگلی سیٹ پر نہیں بیٹھ سکتا سوائے اس کے کہ پچھلی سیٹیں موجود نہ ہوں (اور مناسب چائلڈ سیٹ کے ساتھ)۔"},{"text":"10 سال سے کم عمر بچوں کو کسی بالغ کے بغیر گاڑی میں چھوڑنا خلاف ورزی ہے۔"}]},"hi":{"title":"यात्रियों को ले जाना और सीट बेल्ट","blocks":[{"text":"यात्रियों को केवल उनके लिए बनी गाड़ियों में ले जाने की अनुमति है; गाड़ी के पीछे के डाले (कार्गो हिस्से) में, किसी बाहरी हिस्से पर या ट्रकों में ले जाना मना है।"},{"text":"ड्राइवर और सभी यात्रियों के लिए सीट बेल्ट ज़रूरी है, और ड्राइवर को यात्रियों को याद दिलाना होगा। छूट केवल स्वास्थ्य कारणों से मेडिकल प्रमाण और सरकारी अनुमति के साथ, या शरीर के आकार के कारण मिलती है।"},{"text":"12 साल से कम उम्र के बच्चों को बूस्टर सीट चाहिए ताकि बेल्ट कंधे के नीचे रहे। 10 साल से कम उम्र का बच्चा आगे की सीट पर नहीं बैठ सकता, जब तक पीछे की सीटें न हों (और उपयुक्त सीट के साथ)।"},{"text":"10 साल से कम उम्र के बच्चों को गाड़ी में किसी वयस्क के बिना छोड़ना उल्लंघन है।"}]},"bn":{"title":"যাত্রী বহন ও সিট বেল্ট","blocks":[{"text":"শুধু যাত্রী বহনের জন্য তৈরি গাড়িতেই যাত্রী নেওয়া যায়; গাড়ির পেছনের মালামালের অংশে, কোনো বাইরের অংশে বা ট্রাকে যাত্রী নেওয়া নিষেধ।"},{"text":"চালক ও সব যাত্রীর জন্য সিট বেল্ট বাধ্যতামূলক, এবং চালককে যাত্রীদের মনে করিয়ে দিতে হবে। ছাড় শুধু স্বাস্থ্যগত কারণে মেডিকেল প্রমাণ ও সরকারি অনুমতিসহ, অথবা শরীরের আকারের কারণে।"},{"text":"12 বছরের কম বয়সী শিশুদের বুস্টার সিট দরকার, যাতে বেল্ট কাঁধের নিচে থাকে। 10 বছরের কম বয়সী শিশু সামনের সিটে বসতে পারবে না; তবে গাড়িতে পেছনের সিট না থাকলে উপযুক্ত চাইল্ড সিটে বসানো যাবে।"},{"text":"10 বছরের কম বয়সী শিশুদের কোনো প্রাপ্তবয়স্ক ছাড়া গাড়িতে রেখে যাওয়া লঙ্ঘন।"}]}},"t09":{"en":{"title":"Driving and changing lanes","blocks":[{"text":"On a two-lane road with a broken line: use the right lane and do not cross the line except to overtake. Crossing a double solid line is prohibited."},{"text":"On multi-lane roads, slow vehicles keep to the far right unless they are preparing to turn left."},{"text":"Keep to the far right if you want to turn right, if vehicles are overtaking you, if your speed is lower, if visibility is poor, or if vehicles are coming from the opposite direction."},{"text":"Driving on the left is permitted to overtake, to avoid an accident, or if part of the right side is closed by signs or officials."},{"text":"Narrow sections (bottlenecks): keep right and leave side clearance for oncoming traffic, stop if necessary, and use the horn only when necessary."},{"text":"Changing lanes (MSSSM): mirrors → signal → shoulder check (blind spot) → adjust speed → move smoothly. The higher the speed, the smoother the steering must be."},{"text":"Relying only on the side mirrors leaves you exposed to the blind spot, so look over your shoulder."}]},"ur":{"title":"ڈرائیونگ اور لین تبدیل کرنا","blocks":[{"text":"ٹوٹی ہوئی لکیر والی دو لین سڑک پر: دائیں لین استعمال کریں اور اوورٹیک کے علاوہ لکیر پار نہ کریں۔ دوہری مسلسل لکیر پار کرنا منع ہے۔"},{"text":"کئی لین والی سڑکوں پر سست گاڑیاں بالکل دائیں جانب چلتی ہیں جب تک کہ وہ بائیں مڑنے کی تیاری نہ کر رہی ہوں۔"},{"text":"بالکل دائیں جانب رہیں اگر آپ دائیں مڑنا چاہتے ہوں، یا گاڑیاں آپ کو اوورٹیک کر رہی ہوں، یا آپ کی رفتار کم ہو، یا دکھائی کم ہو، یا مخالف سمت سے گاڑیاں آ رہی ہوں۔"},{"text":"بائیں جانب ڈرائیونگ کی اجازت اوورٹیک کرنے، حادثے سے بچنے، یا ہدایات کے تحت دائیں حصے کا کچھ حصہ بند ہونے کی صورت میں ہے۔"},{"text":"تنگ راستے: دائیں رہیں اور سامنے سے آنے والوں کے لیے ایک طرف جگہ چھوڑیں، ضرورت ہو تو رک جائیں، اور ہارن صرف ضرورت کے وقت استعمال کریں۔"},{"text":"لین تبدیل کرنا (MSSSM): شیشے ← انڈیکیٹر ← کندھے کے اوپر سے دیکھنا (بلائنڈ اسپاٹ) ← رفتار درست کرنا ← آرام سے لین بدلنا۔ رفتار جتنی زیادہ ہو، اسٹیئرنگ اتنا ہی نرم ہونا چاہیے۔"},{"text":"صرف سائیڈ شیشوں پر انحصار آپ کو بلائنڈ اسپاٹ کے خطرے میں ڈالتا ہے، اس لیے کندھے کے اوپر سے دیکھیں۔"}]},"hi":{"title":"गाड़ी चलाना और लेन बदलना","blocks":[{"text":"टूटी लाइन वाली दो-लेन सड़क पर: दाईं लेन का इस्तेमाल करें और ओवरटेक के अलावा लाइन पार न करें। दोहरी लगातार लाइन को पार करना मना है।"},{"text":"कई लेन वाली सड़कों पर धीमी गाड़ियाँ सबसे दाईं ओर चलती हैं, जब तक वे बाएँ मुड़ने की तैयारी न कर रही हों।"},{"text":"सबसे दाईं ओर रहें अगर आप दाएँ मुड़ना चाहते हैं, या गाड़ियाँ आपको ओवरटेक कर रही हैं, या आपकी गति कम है, या दिखाई कम दे रहा है, या सामने की दिशा से गाड़ियाँ आ रही हैं।"},{"text":"बाईं ओर गाड़ी चलाने की अनुमति ओवरटेक करने, दुर्घटना से बचने, या निर्देशों के कारण दाईं ओर का कुछ हिस्सा बंद होने पर है।"},{"text":"संकरे हिस्से (बॉटलनेक): दाईं ओर रहें और सामने से आने वालों के लिए बगल में जगह छोड़ें, ज़रूरत हो तो रुकें, और हॉर्न केवल ज़रूरत पर ही बजाएँ।"},{"text":"लेन बदलना (MSSSM): शीशे → इंडिकेटर → कंधे के ऊपर से देखें (ब्लाइंड स्पॉट) → गति ठीक करें → आराम से आगे बढ़ें। गति जितनी ज़्यादा हो, स्टीयरिंग उतना ही आराम से घुमाना चाहिए।"},{"text":"केवल साइड शीशों पर भरोसा करने से आप ब्लाइंड स्पॉट के खतरे में पड़ते हैं, इसलिए कंधे के ऊपर से देखें।"}]},"bn":{"title":"গাড়ি চালানো ও লেন পরিবর্তন","blocks":[{"text":"ভাঙা দাগওয়ালা দুই লেনের রাস্তায়: ডান লেন ব্যবহার করুন এবং ওভারটেক ছাড়া দাগ পার হবেন না। দুইটি একটানা দাগ পার হওয়া নিষেধ।"},{"text":"বহু লেনের রাস্তায় ধীরগতির যানবাহন একেবারে ডান দিকে চলে, যদি না বাঁয়ে মোড় নেওয়ার প্রস্তুতি নেয়।"},{"text":"একেবারে ডান দিকে থাকুন যদি আপনি ডানে মোড় নিতে চান, বা গাড়ি আপনাকে ওভারটেক করছে, বা আপনার গতি কম, বা দৃশ্যমানতা কম, বা বিপরীত দিক থেকে গাড়ি আসছে।"},{"text":"বাঁ দিক দিয়ে গাড়ি চালানো যায় ওভারটেক করতে, দুর্ঘটনা এড়াতে, অথবা নির্দেশনার কারণে ডান দিকের কিছু অংশ বন্ধ থাকলে।"},{"text":"সরু অংশ (রাস্তা সংকীর্ণ হয়ে যাওয়া জায়গা): ডানে থাকুন এবং বিপরীত দিক থেকে আসা গাড়ির জন্য পাশে জায়গা রাখুন, দরকার হলে থামুন, এবং শুধু প্রয়োজনে হর্ন বাজান।"},{"text":"লেন পরিবর্তন (MSSSM): আয়না → ইন্ডিকেটর → কাঁধের উপর দিয়ে দেখা (ব্লাইন্ড স্পট) → গতি ঠিক করা → মসৃণভাবে সরে যাওয়া। গতি যত বেশি, স্টিয়ারিং তত মসৃণ হতে হবে।"},{"text":"শুধু পাশের আয়নার উপর নির্ভর করলে আপনি ব্লাইন্ড স্পটের ঝুঁকিতে পড়বেন, তাই কাঁধের উপর দিয়ে তাকান।"}]}},"t10":{"en":{"title":"Turning, roundabouts and reversing","blocks":[{"text":"Without markings: turn right from the far right with a tight curve. Turn left from the middle of the road (to the right of the dividing line) on two-way roads, and from the far left on one-way roads, with a wide curve. Where there are arrows, use the lane marked with the arrow for your direction."},{"text":"Plan ahead and choose the correct lane before the intersection, signal early and slow down without sudden braking."},{"text":"Roundabout: vehicles inside it have priority. To turn right use the right-hand (first) lane, to turn left use the left-hand (third) lane, and signal right before your exit. For the second exit, signal at the island of the first exit; for a U-turn, signal at the island of the second exit."},{"text":"Reverse only when necessary and for no more than 20 m. Reversing is prohibited on highways."},{"text":"U-turns are allowed at intersections unless a sign prohibits them."}]},"ur":{"title":"مڑنا، گول چکر اور گاڑی پیچھے کرنا","blocks":[{"text":"نشانات کے بغیر: دائیں مڑنے کے لیے سڑک کے بالکل دائیں جانب سے تنگ موڑ کے ساتھ مڑیں۔ بائیں مڑنے کے لیے دو طرفہ سڑک پر سڑک کے درمیان (درمیانی لائن کے دائیں جانب) سے، اور یک طرفہ سڑک پر بالکل بائیں جانب سے کھلے موڑ کے ساتھ مڑیں۔ تیر کے نشانات ہوں تو وہ لین استعمال کریں جس میں آپ کی سمت کا تیر ہو۔"},{"text":"پہلے سے منصوبہ بندی کریں اور چوراہے سے پہلے صحیح لین منتخب کریں، جلدی انڈیکیٹر دیں اور اچانک بریک لگائے بغیر رفتار کم کریں۔"},{"text":"گول چکر: اندر موجود گاڑیوں کو ترجیح حاصل ہے۔ دائیں مڑنے کے لیے پہلی لین اور بائیں مڑنے کے لیے تیسری لین استعمال کریں، اور اپنے نکلنے کے راستے سے پہلے دایاں انڈیکیٹر دیں۔ دوسرے راستے سے نکلنے کے لیے پہلے راستے کے جزیرے کے پاس انڈیکیٹر دیں، اور یو ٹرن کے لیے دوسرے راستے کے جزیرے کے پاس۔"},{"text":"گاڑی صرف ضرورت کے وقت اور زیادہ سے زیادہ 20 میٹر تک پیچھے کریں۔ ہائی وے پر گاڑی پیچھے کرنا منع ہے۔"},{"text":"چوراہوں پر یو ٹرن کی اجازت ہے، بشرطیکہ کوئی نشان اسے منع نہ کرے۔"}]},"hi":{"title":"मुड़ना, गोल चक्कर और पीछे जाना","blocks":[{"text":"जब सड़क पर निशान न हों: दाएँ मुड़ने के लिए सबसे दाईं ओर से छोटे घुमाव में मुड़ें। बाएँ मुड़ने के लिए दो-तरफ़ा सड़क पर सड़क के बीच से (बीच की लाइन के दाईं ओर से), और एक-तरफ़ा सड़क पर सबसे बाईं ओर से, बड़े घुमाव में मुड़ें। जहाँ तीर के निशान हों, वहाँ उस लेन का इस्तेमाल करें जिसमें आपकी दिशा का तीर हो।"},{"text":"पहले से योजना बनाएँ और चौराहे से पहले सही लेन चुनें, इंडिकेटर जल्दी दें और अचानक ब्रेक लगाए बिना गति कम करें।"},{"text":"गोल चक्कर: अंदर चल रहे वाहनों को पहले जाने का हक़ है। दाएँ मुड़ने के लिए पहली लेन, बाएँ मुड़ने के लिए तीसरी लेन का इस्तेमाल करें, और अपने निकास से पहले दायाँ इंडिकेटर दें। दूसरे निकास के लिए पहले निकास के आइलैंड के पास इंडिकेटर दें, और यू-टर्न के लिए दूसरे निकास के आइलैंड के पास।"},{"text":"पीछे केवल ज़रूरत पड़ने पर और 20 मीटर से ज़्यादा नहीं जाएँ। हाईवे पर पीछे जाना मना है।"},{"text":"चौराहों पर यू-टर्न लेने की अनुमति है, अगर कोई संकेत उसे मना न करे।"}]},"bn":{"title":"মোড় নেওয়া, গোলচত্বর ও পেছনে চালানো","blocks":[{"text":"রাস্তায় দাগ (মার্কিং) না থাকলে: ডানে মোড় নিন একেবারে ডান দিক থেকে, ছোট বাঁকে। বামে মোড় নিন দুইমুখী রাস্তায় রাস্তার মাঝখান থেকে (মাঝের দাগের ডান পাশ থেকে), আর একমুখী রাস্তায় একেবারে বাম দিক থেকে, বড় বাঁকে। তীরচিহ্ন থাকলে সেই লেন ব্যবহার করুন যেখানে আপনার দিকের তীর আছে।"},{"text":"আগে থেকে পরিকল্পনা করুন এবং মোড়ের আগেই সঠিক লেন বেছে নিন, আগেভাগে ইন্ডিকেটর দিন এবং হঠাৎ ব্রেক না করে গতি কমান।"},{"text":"গোলচত্বর: ভেতরে থাকা যানবাহনের অগ্রাধিকার। ডানে মোড় নিতে প্রথম লেন, বামে মোড় নিতে তৃতীয় লেন ব্যবহার করুন, এবং আপনার বের হওয়ার পথের আগে ডান ইন্ডিকেটর দিন। দ্বিতীয় বের হওয়ার পথের জন্য প্রথম বের হওয়ার পথের আইল্যান্ডের কাছে ইন্ডিকেটর দিন, আর ইউ-টার্নের জন্য দ্বিতীয় বের হওয়ার পথের আইল্যান্ডের কাছে।"},{"text":"শুধু প্রয়োজন হলে এবং 20 মিটারের বেশি নয়, এমনভাবে পেছনে চালান। হাইওয়েতে পেছনে চালানো নিষেধ।"},{"text":"মোড়ে ইউ-টার্ন নেওয়া যায়, যদি কোনো চিহ্ন তা নিষেধ না করে।"}]}},"t11":{"en":{"title":"Traffic lights and intersections","blocks":[{"text":"Red: stop at the stop line or where you can see the light, and do not cross the pedestrian crossing. Green: move off carefully and do not enter the intersection if you will get stuck in it. Amber: pay attention and stop if you can do so safely."},{"text":"A flashing amber light means the same as a \"Give way\" sign. A flashing red light means the same as a \"Stop\" sign."},{"text":"Turning right on red: from the far-right lane, with the right indicator on, after stopping for 2–3 seconds, and at less than 15 km/h. It is not allowed if there is a dedicated right-turn lane or a sign prohibiting it."},{"text":"A photo from an automated (Saher) camera does not mean an automatic penalty, as every photo is reviewed manually."},{"text":"A traffic police officer has the highest priority, so stop completely and look in all directions for 3 seconds."}]},"ur":{"title":"ٹریفک سگنل اور چوراہے","blocks":[{"text":"سرخ: اسٹاپ لائن پر یا جہاں سے سگنل نظر آئے وہاں رکیں اور پیدل چلنے والوں کی گزرگاہ پار نہ کریں۔ سبز: احتیاط سے چلیں اور اگر چوراہے میں پھنس جانے کا خدشہ ہو تو اس میں داخل نہ ہوں۔ پیلا: ہوشیار رہیں اور اگر بغیر خطرے کے ممکن ہو تو رک جائیں۔"},{"text":"وقفے وقفے سے جلنے والی پیلی لائٹ «ترجیح دیں» کے نشان کی طرح ہے۔ وقفے وقفے سے جلنے والی سرخ لائٹ «رکیں» کے نشان کی طرح ہے۔"},{"text":"سرخ سگنل پر دائیں مڑنا: بالکل دائیں لین سے، دایاں انڈیکیٹر دے کر، 2–3 سیکنڈ رک کر، اور 15 کلومیٹر فی گھنٹہ سے کم رفتار پر۔ اگر دائیں مڑنے کے لیے الگ لین ہو یا کوئی نشان اسے منع کرے تو اس کی اجازت نہیں۔"},{"text":"خودکار نگرانی والے کیمرے کی تصویر کا مطلب خودبخود جرمانہ نہیں، کیونکہ ہر تصویر کا دستی جائزہ لیا جاتا ہے۔"},{"text":"ٹریفک پولیس اہلکار کو سب سے زیادہ ترجیح حاصل ہے، اس لیے مکمل طور پر رکیں اور 3 سیکنڈ تک ہر طرف دیکھیں۔"}]},"hi":{"title":"ट्रैफिक लाइट और चौराहे","blocks":[{"text":"लाल: स्टॉप लाइन पर या जहाँ से लाइट दिखे वहाँ रुकें, और पैदल यात्री क्रॉसिंग पार न करें। हरी: सावधानी से चलें और अगर चौराहे में फँस जाएँगे तो उसमें न घुसें। पीली: ध्यान दें और अगर बिना खतरे के रुक सकें तो रुकें।"},{"text":"रुक-रुक कर जलने वाली पीली लाइट का मतलब “रास्ता दें” संकेत जैसा है। रुक-रुक कर जलने वाली लाल लाइट का मतलब “रुकें” संकेत जैसा है।"},{"text":"लाल लाइट पर दाएँ मुड़ना: सबसे दाईं ओर से, दायाँ इंडिकेटर देकर, 2–3 सेकंड रुककर, और 15 किमी/घंटा से कम गति पर। अगर दाएँ मुड़ने के लिए अलग लेन हो या कोई संकेत इसे मना करे, तो इसकी अनुमति नहीं है।"},{"text":"“ऑटोमैटिक निगरानी” कैमरे की फ़ोटो का मतलब अपने-आप जुर्माना नहीं है, क्योंकि हर फ़ोटो को इंसान द्वारा जाँचा जाता है।"},{"text":"ट्रैफिक पुलिस वाले का आदेश सबसे ऊपर है, इसलिए पूरी तरह रुकें और 3 सेकंड तक सभी तरफ़ देखें।"}]},"bn":{"title":"ট্রাফিক লাইট ও মোড়","blocks":[{"text":"লাল: স্টপ লাইনে বা যেখান থেকে লাইট দেখা যায় সেখানে থামুন, এবং পথচারী পারাপার পার হবেন না। সবুজ: সাবধানে চলুন এবং মোড়ে আটকে যাবেন মনে হলে তাতে ঢুকবেন না। হলুদ: সতর্ক হোন এবং বিপদ ছাড়া থামতে পারলে থামুন।"},{"text":"জ্বলা-নেভা হলুদ লাইট “পথ ছেড়ে দিন” চিহ্নের মতো। জ্বলা-নেভা লাল লাইট “থামুন” চিহ্নের মতো।"},{"text":"লাল লাইটে ডানে মোড় নেওয়া: একেবারে ডান দিক থেকে, ডান ইন্ডিকেটর দিয়ে, 2–3 সেকেন্ড থেমে, এবং 15 কিমি/ঘণ্টার কম গতিতে। ডানে মোড়ের জন্য আলাদা লেন থাকলে বা কোনো চিহ্ন নিষেধ করলে এটা করা যাবে না।"},{"text":"“স্বয়ংক্রিয় নজরদারি” ক্যামেরার ছবি মানেই স্বয়ংক্রিয় শাস্তি নয়, কারণ প্রতিটি ছবি মানুষ হাতে যাচাই করে।"},{"text":"ট্রাফিক পুলিশের অগ্রাধিকার সবার ওপরে, তাই পুরোপুরি থামুন এবং 3 সেকেন্ড ধরে সব দিকে দেখুন।"}]}},"t12":{"en":{"title":"Right-of-way rules","blocks":[{"text":"Emergency vehicles always have priority."},{"text":"Equal intersection: priority goes to the vehicle closest to the intersection; if both arrive together, to the one coming from the right."},{"text":"A vehicle going straight ahead has priority over one changing direction (turning left or making a U-turn)."},{"text":"Partly blocked road: priority goes to the driver whose side of the road ahead (the right side) is open."},{"text":"Steep slope: the vehicle going downhill keeps close to the right edge and lets the vehicle going uphill pass, stopping if necessary."},{"text":"The main road has priority over a side road, and anyone entering from a side road must give way. A vehicle leaving the main road for a service road has priority."},{"text":"Unclear situation: make eye contact and give up your right of way if that helps safety."},{"text":"Do not enter an intersection if you will get stuck in it, even if the light is green."}]},"ur":{"title":"ترجیح کے قواعد","blocks":[{"text":"ایمرجنسی گاڑیوں کو ہمیشہ ترجیح حاصل ہے۔"},{"text":"برابر کا چوراہا: ترجیح اس گاڑی کو ہے جو چوراہے کے زیادہ قریب ہو، اور اگر دونوں ایک ساتھ پہنچیں تو دائیں طرف سے آنے والی گاڑی کو۔"},{"text":"سیدھی جانے والی گاڑی کو سمت بدلنے والی گاڑی (بائیں مڑنے یا یو ٹرن لینے والی) پر ترجیح حاصل ہے۔"},{"text":"جزوی طور پر بند سڑک: ترجیح اس کو ہے جس کے آگے سڑک اس کی دائیں جانب کھلی ہو۔"},{"text":"تیز ڈھلوان: نیچے اترنے والی گاڑی دائیں کنارے کے قریب ہو جائے اور اوپر چڑھنے والی گاڑی کو گزرنے دے، اور ضرورت ہو تو رک جائے۔"},{"text":"مرکزی سڑک کو ذیلی سڑک پر ترجیح حاصل ہے، اور ذیلی سڑک سے داخل ہونے والا ترجیح دے۔ مرکزی سڑک سے سروس روڈ پر نکلنے والے کو ترجیح حاصل ہے۔"},{"text":"غیر واضح صورتحال: آنکھوں سے رابطہ کریں اور اگر اس سے حفاظت میں مدد ملے تو اپنا حق چھوڑ دیں۔"},{"text":"اگر چوراہے میں پھنس جانے کا خدشہ ہو تو اس میں داخل نہ ہوں، چاہے لائٹ سبز ہو۔"}]},"hi":{"title":"रास्ता देने के नियम","blocks":[{"text":"इमरजेंसी वाहनों को हमेशा पहले जाने का हक़ है।"},{"text":"बराबर का चौराहा: पहले जाने का हक़ उस वाहन का है जो चौराहे के सबसे पास हो, और अगर दोनों एक साथ पहुँचें तो दाईं ओर से आने वाले का।"},{"text":"सीधा जा रहा वाहन दिशा बदलने वाले (बाएँ मुड़ने या यू-टर्न लेने वाले) वाहन से पहले जाएगा।"},{"text":"आंशिक रूप से बंद सड़क: पहले जाने का हक़ उसका है जिसके आगे सड़क उसकी दाईं ओर खुली हो।"},{"text":"तेज़ ढलान: नीचे उतरने वाला वाहन दाएँ किनारे के पास रहे और ऊपर चढ़ने वाले को निकलने दे, और ज़रूरत हो तो रुक जाए।"},{"text":"मुख्य सड़क को छोटी (साइड) सड़क पर प्राथमिकता है, और छोटी सड़क से आने वाला रास्ता देगा। मुख्य सड़क से सर्विस रोड पर जाने वाले को पहले जाने का हक़ है।"},{"text":"साफ़ न हो तो: आँखों से संपर्क करें, और अगर इससे सुरक्षा बढ़े तो अपना हक़ छोड़ दें।"},{"text":"अगर चौराहे में फँस जाएँगे तो उसमें न घुसें, चाहे लाइट हरी हो।"}]},"bn":{"title":"অগ্রাধিকারের নিয়ম","blocks":[{"text":"জরুরি যানবাহনের সবসময় অগ্রাধিকার।"},{"text":"সমান মোড়: অগ্রাধিকার সেই গাড়ির যেটা মোড়ের সবচেয়ে কাছে, আর দুটো একসাথে পৌঁছালে ডান দিক থেকে আসা গাড়ির।"},{"text":"সোজা সামনে যাওয়া গাড়ির অগ্রাধিকার দিক বদলানো (বামে মোড় বা ইউ-টার্ন নেওয়া) গাড়ির চেয়ে বেশি।"},{"text":"আংশিক বন্ধ রাস্তা: অগ্রাধিকার তার, যার সামনের রাস্তা তার ডান পাশে খোলা।"},{"text":"খাড়া উতরাই/ঢাল: নিচে নামা গাড়ি ডান কিনারার কাছে থাকবে এবং ওপরে ওঠা গাড়িকে যেতে দেবে, দরকার হলে থামবে।"},{"text":"প্রধান রাস্তার অগ্রাধিকার শাখা রাস্তার চেয়ে বেশি, আর শাখা রাস্তা থেকে যে ঢোকে সে পথ ছেড়ে দেবে। প্রধান রাস্তা থেকে সার্ভিস রোডে বের হওয়া গাড়ির অগ্রাধিকার।"},{"text":"পরিস্থিতি পরিষ্কার না হলে: চোখে চোখ রেখে যোগাযোগ করুন, আর নিরাপত্তার জন্য সহায়ক হলে নিজের অগ্রাধিকার ছেড়ে দিন।"},{"text":"মোড়ে আটকে যাবেন মনে হলে তাতে ঢুকবেন না, লাইট সবুজ হলেও।"}]}},"t13":{"en":{"title":"Railway crossings","blocks":[{"text":"The train has priority, and the driver must clear the track immediately when a train approaches. Stopping on the track is prohibited."},{"text":"Stop before the X sign when the light is red or amber, when the barriers are moving or closed, when the attendant signals, or if traffic does not allow you to finish crossing."},{"text":"Wait until the barriers are fully open and the red light is off, and make sure no train is approaching."}]},"ur":{"title":"ریلوے کراسنگ","blocks":[{"text":"ٹرین کو ترجیح حاصل ہے، اور ٹرین قریب آنے پر ڈرائیور کو فوراً پٹری خالی کرنی چاہیے۔ پٹری پر رکنا منع ہے۔"},{"text":"X نشان سے پہلے رک جائیں جب لائٹ سرخ یا پیلی ہو، پھاٹک حرکت میں ہوں یا بند ہوں، گارڈ اشارہ کرے، یا ٹریفک آپ کو کراسنگ مکمل کرنے نہ دے۔"},{"text":"پھاٹک مکمل طور پر کھلنے اور سرخ لائٹ بند ہونے تک انتظار کریں، اور یقینی بنائیں کہ کوئی ٹرین قریب نہیں آ رہی۔"}]},"hi":{"title":"रेलवे क्रॉसिंग","blocks":[{"text":"ट्रेन को पहले जाने का हक़ है, और ट्रेन पास आने पर ड्राइवर को तुरंत पटरी ख़ाली करनी चाहिए। पटरी पर रुकना मना है।"},{"text":"X संकेत से पहले रुकें: जब लाइट लाल या पीली हो, जब गेट खुल या बंद हो रहे हों, जब गार्ड इशारा करे, या जब ट्रैफिक के कारण आप क्रॉसिंग पूरी पार न कर सकें।"},{"text":"गेट पूरी तरह खुलने और लाल लाइट बुझने तक इंतज़ार करें, और पक्का करें कि कोई ट्रेन नहीं आ रही है।"}]},"bn":{"title":"রেলক্রসিং","blocks":[{"text":"ট্রেনের অগ্রাধিকার, এবং ট্রেন কাছে এলে চালককে সাথে সাথে লাইন খালি করতে হবে। রেললাইনের ওপর থামা নিষেধ।"},{"text":"X চিহ্নের আগে থামুন: যখন লাইট লাল বা হলুদ, যখন গেট নড়ছে বা বন্ধ, যখন গার্ড ইশারা করে, অথবা যখন ট্রাফিকের কারণে পুরো পার হওয়া সম্ভব নয়।"},{"text":"গেট পুরোপুরি খোলা এবং লাল লাইট নিভে যাওয়া পর্যন্ত অপেক্ষা করুন, এবং নিশ্চিত হোন যে কোনো ট্রেন আসছে না।"}]}},"t14":{"en":{"title":"Speed and safe distance","blocks":[{"text":"Small vehicles: follow the speed limit posted on the road; large vehicles: 50 km/h maximum inside cities. The sign shows the maximum limit, not a required speed."},{"text":"Reduce speed at intersections, crossings, on slippery roads and bends, in congestion, near pedestrians and animals, and in sandstorms, fog and rain."},{"text":"Keep a safety gap of at least two seconds behind the vehicle in front. Choose a reference point and count \"one thousand and one, one thousand and two\" after the vehicle ahead passes it. Increase the gap in bad weather, with heavy loads and behind motorcycles."},{"text":"Economical driving: look ahead and lift your foot off the accelerator early to slow down without braking, which reduces fuel consumption and brake wear. Avoid unnecessary stops."},{"text":"Unnecessary sudden braking and driving so slowly that it obstructs traffic are prohibited."}]},"ur":{"title":"رفتار اور محفوظ فاصلہ","blocks":[{"text":"چھوٹی گاڑیاں: سڑک پر مقرر کردہ رفتار کے مطابق، اور بڑی گاڑیاں شہروں کے اندر زیادہ سے زیادہ 50 کلومیٹر فی گھنٹہ۔ بورڈ پر لکھی رفتار زیادہ سے زیادہ حد ہے، لازمی رفتار نہیں۔"},{"text":"چوراہوں، کراسنگز، پھسلن والی سڑکوں، موڑوں، رش، پیدل چلنے والوں اور جانوروں کے پاس، اور ریت کے طوفان، دھند اور بارش میں رفتار کم کریں۔"},{"text":"اگلی گاڑی کے پیچھے کم از کم دو سیکنڈ کا محفوظ فاصلہ رکھیں۔ کوئی حوالہ نقطہ منتخب کریں اور اگلی گاڑی کے وہاں سے گزرنے کے بعد «ایک ہزار ایک، ایک ہزار دو» گنیں۔ خراب موسم، بھاری بوجھ اور موٹر سائیکلوں کے پیچھے یہ فاصلہ بڑھا دیں۔"},{"text":"کفایتی ڈرائیونگ: آگے دیکھیں اور بریک کے بغیر رفتار کم کرنے کے لیے پہلے سے ایکسیلیٹر سے پاؤں ہٹا لیں، اس سے ایندھن کی کھپت اور بریک کی گھسائی کم ہوتی ہے۔ بلاوجہ رکنے سے بچیں۔"},{"text":"بلا ضرورت اچانک بریک لگانا اور اتنی سست رفتاری جس سے ٹریفک میں رکاوٹ ہو، دونوں منع ہیں۔"}]},"hi":{"title":"गति और सुरक्षित दूरी","blocks":[{"text":"छोटे वाहन: सड़क पर तय गति सीमा के अनुसार; बड़े वाहन: शहरों के अंदर अधिकतम 50 किमी/घंटा। बोर्ड पर लिखी गति अधिकतम सीमा है, ज़रूरी गति नहीं।"},{"text":"चौराहों, क्रॉसिंग, फिसलन वाली सड़कों, मोड़ों, भीड़, पैदल यात्रियों, जानवरों, रेत के तूफ़ान, कोहरे और बारिश में गति कम करें।"},{"text":"आगे वाले वाहन के पीछे कम से कम दो सेकंड की सुरक्षित दूरी रखें। एक निशान (पॉइंट) चुनें और आगे वाले वाहन के उसे पार करने के बाद “एक हज़ार एक, एक हज़ार दो” गिनें। खराब मौसम में, भारी सामान होने पर और दोपहिया वाहनों के पीछे यह दूरी बढ़ाएँ।"},{"text":"किफ़ायती ड्राइविंग: आगे देखें और जल्दी एक्सेलरेटर से पैर हटाएँ ताकि बिना ब्रेक के गति कम हो, इससे ईंधन कम ख़र्च होता है और ब्रेक कम घिसते हैं। बिना ज़रूरत रुकने से बचें।"},{"text":"बिना ज़रूरत अचानक ब्रेक लगाना और इतना धीरे चलाना कि ट्रैफिक रुके, दोनों मना हैं।"}]},"bn":{"title":"গতি ও নিরাপদ দূরত্ব","blocks":[{"text":"ছোট যানবাহন: রাস্তায় নির্ধারিত গতিসীমা অনুযায়ী; বড় যানবাহন: শহরের ভেতরে সর্বোচ্চ 50 কিমি/ঘণ্টা। বোর্ডে লেখা গতি হলো সর্বোচ্চ সীমা, বাধ্যতামূলক গতি নয়।"},{"text":"মোড়, ক্রসিং, পিচ্ছিল রাস্তা, বাঁক, ভিড়, পথচারী, পশু, বালুঝড়, কুয়াশা ও বৃষ্টিতে গতি কমান।"},{"text":"সামনের গাড়ির পেছনে কমপক্ষে দুই সেকেন্ডের নিরাপদ দূরত্ব রাখুন। একটি স্থির জায়গা (রেফারেন্স পয়েন্ট) বেছে নিন এবং সামনের গাড়ি সেটা পার হওয়ার পর “এক হাজার এক, এক হাজার দুই” গুনুন। খারাপ আবহাওয়ায়, ভারী মাল থাকলে এবং দুই চাকার যানের পেছনে এই দূরত্ব বাড়ান।"},{"text":"সাশ্রয়ী ড্রাইভিং: সামনে দেখুন এবং আগেভাগে অ্যাক্সিলারেটর থেকে পা তুলে নিন যাতে ব্রেক ছাড়াই গতি কমে, এতে জ্বালানি কম খরচ হয় এবং ব্রেক কম ক্ষয় হয়। অকারণে থামা এড়িয়ে চলুন।"},{"text":"অকারণে হঠাৎ ব্রেক করা এবং এত ধীরে চালানো যে ট্রাফিকে বাধা হয়, দুটোই নিষেধ।"}]}}};
